import java.util.*;

class Node {
    int val;
    Node left;
    Node right;
    Node(int val) { this.val = val; }
}

public int[][] swapNodes(int[][] indexes, int[] queries) {
    int n = indexes.length;
    Node[] nodes = new Node[n + 1];           // 1-based: nodes[i] is node i
    for (int i = 1; i <= n; i++) nodes[i] = new Node(i);
    for (int i = 1; i <= n; i++) {
        int l = indexes[i - 1][0];            // row i-1 describes node i
        int r = indexes[i - 1][1];
        if (l != -1) nodes[i].left = nodes[l];
        if (r != -1) nodes[i].right = nodes[r];
    }
    Node root = nodes[1];                     // root is node 1, depth 1

    int[][] result = new int[queries.length][];
    for (int q = 0; q < queries.length; q++) {
        swapAtDepth(root, 1, queries[q]);     // cumulative mutation
        List<Integer> out = new ArrayList<>();
        inorder(root, out);
        result[q] = out.stream().mapToInt(Integer::intValue).toArray();
    }
    return result;
}

private void swapAtDepth(Node node, int depth, int k) {
    if (node == null) return;
    if (depth % k == 0) {                     // swap child LINKS
        Node tmp = node.left;
        node.left = node.right;
        node.right = tmp;
    }
    swapAtDepth(node.left, depth + 1, k);
    swapAtDepth(node.right, depth + 1, k);
}

private void inorder(Node node, List<Integer> out) {
    if (node == null) return;
    inorder(node.left, out);
    out.add(node.val);
    inorder(node.right, out);
}

