class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def swap_nodes(indexes: list[list[int]], queries: list[int]) -> list[list[int]]:
    n = len(indexes)
    nodes = [None] * (n + 1)                  # 1-based: nodes[i] is node i
    for i in range(1, n + 1):
        nodes[i] = Node(i)
    for i in range(1, n + 1):
        l, r = indexes[i - 1]                 # row i-1 describes node i
        if l != -1:
            nodes[i].left = nodes[l]
        if r != -1:
            nodes[i].right = nodes[r]
    root = nodes[1]                           # root is node 1, depth 1

    def swap_at_depth(node, depth, k):
        if node is None:
            return
        if depth % k == 0:                    # swap child LINKS
            node.left, node.right = node.right, node.left
        swap_at_depth(node.left, depth + 1, k)
        swap_at_depth(node.right, depth + 1, k)

    def inorder(node, out):
        if node is None:
            return
        inorder(node.left, out)
        out.append(node.val)
        inorder(node.right, out)

    result = []
    for k in queries:
        swap_at_depth(root, 1, k)             # cumulative mutation
        out = []
        inorder(root, out)
        result.append(out)
    return result

