import java.util.*;

public int[][] swapNodes(int[][] indexes, int[] queries) {
    int n = indexes.length;
    Node[] nodes = new Node[n + 1];
    for (int i = 1; i <= n; i++) nodes[i] = new Node(i);
    for (int i = 1; i <= n; i++) {
        if (indexes[i - 1][0] != -1) nodes[i].left = nodes[indexes[i - 1][0]];
        if (indexes[i - 1][1] != -1) nodes[i].right = nodes[indexes[i - 1][1]];
    }
    Node root = nodes[1];

    // BFS: bucket nodes by depth (depth never changes under swaps)
    Map<Integer, List<Node>> buckets = new HashMap<>();
    Queue<Node> bfs = new LinkedList<>();
    Queue<Integer> depths = new LinkedList<>();
    bfs.offer(root); depths.offer(1);
    int maxDepth = 0;
    while (!bfs.isEmpty()) {
        Node node = bfs.poll();
        int d = depths.poll();
        maxDepth = Math.max(maxDepth, d);
        buckets.computeIfAbsent(d, x -> new ArrayList<>()).add(node);
        if (node.left != null)  { bfs.offer(node.left);  depths.offer(d + 1); }
        if (node.right != null) { bfs.offer(node.right); depths.offer(d + 1); }
    }

    int[][] result = new int[queries.length][];
    for (int q = 0; q < queries.length; q++) {
        int k = queries[q];
        for (int d = k; d <= maxDepth; d += k) {        // depths k, 2k, 3k, ...
            for (Node node : buckets.getOrDefault(d, List.of())) {
                Node tmp = node.left; node.left = node.right; node.right = tmp;
            }
        }
        result[q] = inorderIterative(root);
    }
    return result;
}

private int[] inorderIterative(Node root) {
    List<Integer> out = new ArrayList<>();
    Deque<Node> stack = new ArrayDeque<>();
    Node cur = root;
    while (cur != null || !stack.isEmpty()) {
        while (cur != null) { stack.push(cur); cur = cur.left; }
        cur = stack.pop();
        out.add(cur.val);
        cur = cur.right;
    }
    return out.stream().mapToInt(Integer::intValue).toArray();
}

