from collections import deque, defaultdict

def swap_nodes(indexes: list[list[int]], queries: list[int]) -> list[list[int]]:
    n = len(indexes)
    nodes = [None] * (n + 1)
    for i in range(1, n + 1):
        nodes[i] = Node(i)
    for i in range(1, n + 1):
        l, r = indexes[i - 1]
        if l != -1:
            nodes[i].left = nodes[l]
        if r != -1:
            nodes[i].right = nodes[r]
    root = nodes[1]

    # BFS: bucket nodes by depth (depth never changes under swaps)
    buckets = defaultdict(list)
    bfs = deque([(root, 1)])
    max_depth = 0
    while bfs:
        node, d = bfs.popleft()
        max_depth = max(max_depth, d)
        buckets[d].append(node)
        if node.left:
            bfs.append((node.left, d + 1))
        if node.right:
            bfs.append((node.right, d + 1))

    def inorder_iterative(node):
        out, stack, cur = [], [], node
        while cur is not None or stack:
            while cur is not None:
                stack.append(cur)
                cur = cur.left
            cur = stack.pop()
            out.append(cur.val)
            cur = cur.right
        return out

    result = []
    for k in queries:
        for d in range(k, max_depth + 1, k):       # depths k, 2k, 3k, ...
            for node in buckets[d]:
                node.left, node.right = node.right, node.left
        result.append(inorder_iterative(root))
    return result
